    "1952": {
        "codebook_rule": [
            "1"
        ],
        "document_id": "1952",
        "explanation": "Sen. Murkowski is taking credit for securing a contract for an Alaska natural gas pipeline, which matches Rule 1.",
        "label": "1"
    },
    "2168": {
        "codebook_rule": [
            "1"
        ],
        "document_id": "2168",
        "explanation": "Sen. Snowe is taking credit for introducing legislation to reduce calling costs for troops, which matches Rule 1.",
        "label": "1"
    },
    "2176": {
        "codebook_rule": [
            "1"
        ],
        "document_id": "2176",
        "explanation": "Sen. Grassley is taking credit for securing $2.4 million in federal grant funding for 23 fire departments in Iowa, which matches Rule 1.",
        "label": "1"
    },
    "2964": {
        "codebook_rule": [
            "1"
        ],
        "document_id": "2964",
        "explanation": "Sen. Chafee is taking credit for securing a $500,000 federal grant for a program in his state, which matches Rule 1.",
        "label": "1"
    },
    "3199": {
        "codebook_rule": [
            "1"
        ],
        "document_id": "3199",
        "explanation": "Sen. Murray is taking credit for presenting an award to a Seattle housing project, which matches Rule 1.",
        "label": "1"
    },
    "3291": {
        "codebook_rule": [
            "1"
        ],
        "document_id": "3291",
        "explanation": "Sen. Shelby is taking credit for securing $225,000 in federal funds for a fire department in his state, which matches Rule 1.",
        "label": "1"
    },
    "3303": {
        "codebook_rule": [
            "1"
        ],
        "document_id": "3303",
        "explanation": "Sen. Martinez is taking credit for calling for sanctions against the Sudanese government, which matches Rule 1.",
        "label": "1"
    },
    "3859": {
        "codebook_rule": [
            "1"
        ],
        "document_id": "3859",
        "explanation": "Sen. Collins is taking credit for announcing $144,184 in grant funding for three Maine fire departments, which matches Rule 1.",
        "label": "1"
    },
    "4791": {
        "codebook_rule": [
            "1"
        ],
        "document_id": "4791",
        "explanation": "Sen. Domenici is taking credit for announcing over $450,000 in DHS grants for 25 New Mexico communities, which matches Rule 1.",
        "label": "1"
    }
}

{
  "1421": {
    "codebook_rule": ["2"],
    "document_id": "1421",
    "explanation": "The senator says, \"That's why Senator Specter and I have introduced legislation to expand the number of stem cell lines that are eligible for federally funded research.\" This is a direct assertion of responsibility for introducing a specific legislative proposal. Although the text also says \"I was pleased to learn that NIH is supporting five clinical trials on ALS,\" that is an announcement of an existing NIH action, not a claim that the senator secured, delivered, or helped obtain that support. The only applicable credit-claiming language is the statement that he and Senator Specter introduced legislation.",
    "label": "1"
  },
  "2049": {
    "codebook_rule": ["3"],
    "document_id": "2049",
    "explanation": "The press release states that Senator Snowe \"today sent a letter to John Negroponte, Director of National Intelligence, raising questions and concerns about a newly revealed National Security Agency (NSA) program.\" Sending a letter to a federal official about a program is an action intended to influence the executive branch or an agency. Because the text describes this direct intervention, Rule 3 applies. The text does not claim that the senator secured funds or that the intervention produced a favorable outcome, but the letter-sending itself is covered by the text of Rule 3.",
    "label": "1"
  },
  "2939": {
    "codebook_rule": ["1", "2"],
    "document_id": "2939",
    "explanation": "The press release announces that the Woodlawn Fire Department will receive $98,632 as part of the FIRE Act, and says Senator DeWine \"wrote and passed the FIRE Act (S. 1941) in 2000.\" It also says he \"helped secure $650 million for the FIRE Act\" in the fiscal year 2005 appropriations process and that he \"passed an updated version of the bill\" in fiscal year 2004. These statements claim credit both for securing federal grant funding for a local fire department and for authoring/passing legislation that provides that funding.",
    "label": "1"
  },
  "305": {
    "codebook_rule": ["2"],
    "document_id": "305",
    "explanation": "The press release says Senator Inhofe \"today praised the inclusion of his legislation requiring parental consent for non-emergency intrusive physical examinations in the Federal Drug Administration Reauthorization Act of 2007 (S.1082) which today passed the Senate (93-1).\" It also notes that he introduced the legislation in multiple Congresses and that the Senate action is \"another step in the right direction.\" This is a claim of credit for the inclusion and passage of his legislation in a bill that passed the Senate.",
    "label": "1"
  },
  "3119": {
    "codebook_rule": ["1", "3"],
    "document_id": "3119",
    "explanation": "The press release says Senator Conrad \"today continued to fight for Northwood North Dakota and reiterated the need for federal disaster aid\" and that he \"sent a letter to FEMA Administrator R David Paulison yesterday urging him to immediately approve Individual Assistance for families in Northwood.\" The letter to FEMA is a direct attempt to influence an agency decision about disaster assistance. The overall message also announces/supports the receipt of federal disaster aid for the community, which is a desirable federal outcome for the state. However, the text does not say FEMA has approved the aid; it only says he urged approval. Thus, the strongest claim is that he is seeking federal disaster aid and taking action to influence FEMA.",
    "label": "1"
  },
  "3332": {
    "codebook_rule": [],
