{
  "1160": {
    "codebook_rule": ["1", "3"],
    "document_id": "1160",
    "explanation": "The senators announce that the Senate Appropriations Committee approved $30 million for non-federal levee repairs in Terrebonne Parish. This is an announcement of a favorable federal funding outcome for the state, satisfying Rule 1. The text also claims that their 'constant pushing and prodding' of committee chairs 'has paid off' with the inclusion of this funding, which fits Rule 3's claim that direct intervention led to a favorable action by a federal entity.",
    "label": "1"
  },
  "1231": {
    "codebook_rule": ["2"],
    "document_id": "1231",
    "explanation": "Senator Domenici claims credit for the bipartisan national energy conference report and says the Senate is expected to pass it. He highlights the benefits of the bill and his role in the process. This satisfies Rule 2 because it concerns a legislative milestone and successful legislative product that the senator authored/championed. It is not merely a position-taking statement; it emphasizes the legislative outcome and benefits.",
    "label": "1"
  },
  "2875": {
    "codebook_rule": ["1"],
    "document_id": "2875",
    "explanation": "Senators Snowe and Collins announce that the omnibus appropriations bill includes more than $2.3 million in federal funding for Maine health care and education projects, including specific earmarked amounts and projects. This directly satisfies Rule 1: announcing secured/delivered federal funds or projects for the state.",
    "label": "1"
  },
  "335": {
    "codebook_rule": [],
    "document_id": "335",
    "explanation": "Senator Rockefeller comments on the House's failure to override a CHIP veto. He discusses a legislative setback, urges future action, and criticizes Republicans. He does not claim credit for a realized favorable outcome, secured funding, legislative passage, agency decision, or appointment. Thus no rule applies and label is 0.",
    "label": "0"
  },
  "3550": {
    "codebook_rule": [],
    "document_id": "3550",
    "explanation": "Senator Dodd issues a statement on the death of Saddam Hussein. This is a general foreign-policy/justice statement, not a claim of credit for a desirable outcome for his state or constituents, nor does it involve funding, legislative passage, agency decision, or appointment. No rule applies.",
    "label": "0"
  },
  "4179": {
    "codebook_rule": [],
    "document_id": "4179",
    "explanation": "Senator Cornyn co-sponsors and introduces the Patent Reform Act of 2007. Introducing or co-sponsoring a bill is position-taking, not a realized legislative outcome. No passage, enactment, or secured benefit is claimed. Therefore no rule applies.",
    "label": "0"
  },
  "4634": {
    "codebook_rule": [],
    "document_id": "4634",
    "explanation": "The Wyoming delegation asks the Forest Service to seek community opinion and host a public meeting regarding a possible office relocation. This is advocacy/pressure on an agency, but there is no favorable agency outcome yet. No rule applies.",
    "label": "0"
  },
  "4651": {
    "codebook_rule": [],
    "document_id": "4651",
    "explanation": "Senator Collins met with a Prudential Spirit of Community honoree to congratulate her. The text does not state that the senator successfully nominated or recommended her for this honor; it merely describes a meeting/recognition. Rule 4 requires claiming credit for successfully nominating or recommending someone. Thus no rule applies.",
    "label": "0"
  },
  "935": {
    "codebook_rule": ["3"],
    "document_id": "935",
    "explanation": "Senator Mikulski received a promise from appropriations subcommittee leaders to fight for funding for a program she created. This can be read as a favorable commitment from congressional appropriators resulting from her advocacy/program creation, fitting Rule 3 in a broad sense: direct engagement led to a favorable action/commitment. However, there is ambiguity: it is not yet secured funding and the actors are legislators rather than an agency/executive branch. If strictly interpreting Rule 3 as requiring an agency/executive decision or a realized outcome, this could be 0. Given the title 'SECURES PROMISE' and the explicit promise to fight for funding, I classified it as credit-claiming under Rule 3.",
    "label": "1"
  },
  "981": {
    "codebook_rule": [],
    "document_id": "981",
    "explanation": "Senator Whitehouse issues a statement on climate change, attends a hearing, and discusses cosponsoring legislation. This is position-taking and advocacy, not a claimed successful outcome, funding, passage, agency decision, or appointment. No rule applies.",
    "label": "0"
  }
}

{
