  },
  "338": {
    "codebook_rule": ["1"],
    "document_id": "338",
    "explanation": "Senator Harkin announces that workers from First Choice Distribution will be eligible for job training assistance through the Trade Adjustment Assistance Act, expanding on a Department of Labor declaration. This announces a favorable federal benefit/assistance outcome for local workers, which fits Rule 1's announcement of federal funds/benefits to state or local entities. It may also resemble Rule 3 if Harkin's involvement led to the agency determination, but the text does not explicitly state his direct intervention caused the decision; Rule 1 is sufficient.",
    "label": "1"
  },
  "3857": {
    "codebook_rule": [],
    "document_id": "3857",
    "explanation": "Senator Levin gives memorial remarks honoring Rosa Parks and recounts his past civil rights work. He does not claim credit for securing federal funds, passing legislation, influencing an agency decision, or making appointments. The text is commemorative, not credit-claiming.",
    "label": "0"
  },
  "4356": {
    "codebook_rule": ["1", "2"],
    "document_id": "4356",
    "explanation": "Senators Frist and Alexander announce that the FY2006 Military Construction Appropriations bill passed by the Senate includes over $288 million for Tennessee military construction projects. This is credit-claiming under Rule 1 because they announce/deliver federal funding for projects in their state. It also fits Rule 2 because they highlight the successful passage of an appropriations bill that includes specific benefits for Tennessee.",
    "label": "1"
  },
  "4477": {
    "codebook_rule": ["2", "3"],
    "document_id": "4477",
    "explanation": "Senators Sununu, Craig, Murkowski, and Hagel announce they have reached an agreement with the White House regarding reauthorization of the USA PATRIOT Act, with specific modifications to protect civil liberties. This is a claimed successful outcome from negotiations with the executive branch, fitting Rule 3. It also resembles Rule 2 in that they announce progress/agreement on legislation they helped shape, although the release describes an agreement rather than final passage. The key credit-claim is reaching an agreement that changes the legislative package.",
    "label": "1"
  },
  "4667": {
    "codebook_rule": [],
    "document_id": "4667",
    "explanation": "Senator Martinez speaks in support of a flag desecration constitutional amendment and urges Congress to support it. The statement expresses support and advocacy, but does not claim that the amendment passed, was included in legislation, or that he secured a specific outcome. Thus it is position-taking, not credit-claiming.",
    "label": "0"
  },
  "643": {
    "codebook_rule": [],
    "document_id": "643",
    "explanation": "Senator Leahy discusses Senate progress on immigration reform, praises other senators, and urges passage of the committee bill and amendments. Although he mentions committee passage and approved amendments, the statement primarily describes ongoing legislative debate and supports future votes. It does not clearly claim credit by Leahy for a specific successful passage of a bill/amendment/resolution he authored or championed. Rule 2 requires a realized legislative victory tied to the senator's credit; here it is more general floor advocacy.",
    "label": "0"
  }
}

{
    "1079": {
